/** Case-insensitive lookup of a semantically verified example. */
export function getSwedishSemanticFix(headword: string): SwedishExampleFix | undefined {
  const key = (headword || "").trim();
  return (
    SWEDISH_EXAMPLE_SEMANTIC_FIXES[key] ||
    SWEDISH_EXAMPLE_SEMANTIC_FIXES[key.toLowerCase()]
  );
}
